// Topographic map: contour lines over fbm terrain.
// Lines are anti-aliased in screen space via fwidth(), so they stay
// uLineWidth pixels thick (default 1px) at any layer resolution.
uniform float uScale;      // @param 2.5 0.5 10
uniform float uLevels;     // @param 28 4 100
uniform float uSpeed;      // @param 0.04 0 1
uniform float uLineWidth;  // @param 1.0 0.5 3
uniform float uIndexEvery; // @param 5 0 10
uniform float uLineAlpha;  // @param 0.55 0 1
uniform float uTintAmount; // @param 0.35 0 1
uniform vec3  uPaper;      // @param #EFE6D2
uniform vec3  uInk;        // @param #6B4A2B
uniform vec3  uLowTint;    // @param #B9D3A8
uniform vec3  uHighTint;   // @param #E2C49A

void main() {
  vec2 p = (uv - 0.5) * vec2(iResolution.x / iResolution.y, 1.0);
  float t = iTime * uSpeed;

  // Terrain height: broad landforms + detail
  float h = 0.65 * fbm(p * uScale + vec2(t, -t * 0.7))
          + 0.35 * fbm(p * uScale * 0.45 + vec2(-3.7, 1.9) - t * 0.3);

  // Contour field
  float v  = h * uLevels;
  float fw = max(fwidth(v), 1e-5);
  float d  = abs(fract(v + 0.5) - 0.5) / fw;          // distance to nearest contour, in pixels
  float line = clamp(0.5 * uLineWidth - d + 0.5, 0.0, 1.0); // pixel coverage

  // Index contours (every Nth level) drawn darker, same 1px thickness
  float alpha = uLineAlpha;
  if (uIndexEvery >= 1.0) {
    float idx = mod(floor(v + 0.5), floor(uIndexEvery));
    if (idx < 0.5) alpha = 1.0;
  }

  // Hypsometric paper tint
  float e = smoothstep(0.25, 0.75, h);
  vec3 tint = mix(uLowTint, uHighTint, e);
  vec3 col = mix(uPaper, uPaper * tint * 1.08, uTintAmount);

  col = mix(col, uInk, line * alpha);
  fragColor = vec4(col, 1.0);
}
